              <span class="chip__ok" [class.show]="copied() === className">✓</span>
            </button>
          }
        </div>
      }
    </div>

    @if (elevations().length === 0) {
      <p class="empty">No elevation tokens found in the loaded stylesheet.</p>
    }
  `,
  styles: `
