  color: #757575;
}
.copied {
  position: absolute;
  right: 0.5rem;
  top: 1rem;
  font-size: 0.7rem;
  color: #0a7d34;
  opacity: 0;
  transition: opacity 0.15s;
}
.copied.show {
  opacity: 1;
}
.empty {
  color: #757575;
}

